B.apb=new A.aN("Sa\u2019i on arrival","\u0627\u0644\u0633\u0639\u064a \u0639\u0646\u062f \u0627\u0644\u0642\u062f\u0648\u0645")
B.ape=new A.aN("Umrah Sa\u2019i","\u0633\u0639\u064a \u0627\u0644\u0639\u0645\u0631\u0629")
B.apj=new A.aN("Qiran/Ifrad: do your Sa\u2019i here OR after Tawaf al-Ifadah, not both. Tamattu\u2019: Umrah Sa\u2019i is followed later by a separate Hajj Sa\u2019i.","\u0644\u0644\u0642\u0627\u0631\u0646 \u0648\u0627\u0644\u0645\u0641\u0631\u062f: \u0627\u0644\u0633\u0639\u064a \u0647\u0646\u0627 \u0623\u0648 \u0628\u0639\u062f \u0637\u0648\u0627\u0641 \u0627\u0644\u0625\u0641\u0627\u0636\u0629\u060c \u0644\u0627 \u0641\u064a \u0627\u0644\u0645\u0648\u0636\u0639\u064a\u0646. \u0648\u0644\u0644\u0645\u062a\u0645\u062a\u0639 \u0633\u0639\u064a \u0644\u0644\u0639\u0645\u0631\u0629 \u062b\u0645 \u0633\u0639\u064a \u0622\u062e\u0631 \u0644\u0644\u062d\u062c.")
B.apt=new A.aN("Begin with Umrah","\u0627\u0628\u062f\u0623 \u0628\u0627\u0644\u0639\u0645\u0631\u0629")
B.Pf=new A.aN("Safa & Marwah","\u0627\u0644\u0635\u0641\u0627 \u0648\u0627\u0644\u0645\u0631\u0648\u0629")
B.aq_=new A.aN("Not due solely for Ifrad. This step remains available for anyone offering a sacrifice.","\u0644\u0627 \u064a\u062c\u0628 \u0644\u0645\u062c\u0631\u062f \u0627\u0644\u0625\u0641\u0631\u0627\u062f. \u062a\u0628\u0642\u0649 \u0647\u0630\u0647 \u0627\u0644\u062e\u0637\u0648\u0629 \u0645\u062a\u0627\u062d\u0629 \u0644\u0645\u0646 \u064a\u0630\u0628\u062d \u0647\u062f\u064a\u064b\u0627.")
B.aq3=new A.aN("Normally due for Tamattu\u2019/Qiran; exemptions and alternatives apply (Qur\u2019an 2:196). Check your arrangements with your group.","\u064a\u062c\u0628 \u0639\u0627\u062f\u0629 \u0644\u0644\u0645\u062a\u0645\u062a\u0639 \u0648\u0627\u0644\u0642\u0627\u0631\u0646 \u0645\u0639 \u0648\u062c\u0648\u062f \u0627\u0633\u062a\u062b\u0646\u0627\u0621\u0627\u062a \u0648\u0628\u062f\u0627\u0626\u0644 (\u0627\u0644\u0628\u0642\u0631\u0629 \u0661\u0669\u0666). \u0631\u0627\u062c\u0639 \u062a\u0631\u062a\u064a\u0628\u0627\u062a\u0643 \u0645\u0639 \u0645\u062c\u0645\u0648\u0639\u062a\u0643.")
B.aq7=new A.aN("Umrah Tawaf","\u0637\u0648\u0627\u0641 \u0627\u0644\u0639\u0645\u0631\u0629")
B.aqb=new A.aN("Qiran/Ifrad: only if you have not already performed Sa\u2019i on arrival. Tamattu\u2019: a separate Hajj Sa\u2019i is needed.","\u0644\u0644\u0642\u0627\u0631\u0646 \u0648\u0627\u0644\u0645\u0641\u0631\u062f \u0625\u0630\u0627 \u0644\u0645 \u064a\u0633\u0639\u064a\u0627 \u0639\u0646\u062f \u0627\u0644\u0642\u062f\u0648\u0645. \u0623\u0645\u0627 \u0627\u0644\u0645\u062a\u0645\u062a\u0639 \u0641\u0639\u0644\u064a\u0647 \u0633\u0639\u064a \u0645\u0633\u062a\u0642\u0644 \u0644\u0644\u062d\u062c.")
B.aql=new A.aN("For Tamattu\u2019, this is Umrah Tawaf. For Qiran/Ifrad, arrival Tawaf is distinct from Tawaf al-Ifadah; late arrivals should follow their group\u2019s guidance.","\u0644\u0644\u0645\u062a\u0645\u062a\u0639 \u0637\u0648\u0627\u0641 \u0627\u0644\u0639\u0645\u0631\u0629\u060c \u0648\u0644\u0644\u0642\u0627\u0631\u0646 \u0648\u0627\u0644\u0645\u0641\u0631\u062f \u0637\u0648\u0627\u0641 \u0627\u0644\u0642\u062f\u0648\u0645 \u0648\u0647\u0648 \u063a\u064a\u0631 \u0637\u0648\u0627\u0641 \u0627\u0644\u0625\u0641\u0627\u0636\u0629. \u0627\u0644\u0645\u062a\u0623\u062e\u0631 \u0641\u064a \u0627\u0644\u0648\u0635\u0648\u0644 \u064a\u062a\u0628\u0639 \u062a\u0648\u062c\u064a\u0647 \u0645\u062c\u0645\u0648\u0639\u062a\u0647.")
